import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor matmul(torch::Tensor A, torch::Tensor B);
"""

matmul_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>
#include <mma.h>
using namespace cute;
using namespace nvcuda;

// Tiled GEMM: C = A * B, all row-major [N, N] float32
// Each CTA computes a 128x128 tile of C with 256 threads,
// staging 128x16 A-tiles and 16x128 B-tiles in shared memory.
// Optimization: tensor-core mma via TF32 WMMA fragments for the
// rank-k updates, fed by a double-buffered cp.async smem pipeline.
__device__ __forceinline__ void cp_async_16(void* smem_dst, void const* gmem_src) {
#if __CUDA_ARCH__ >= 800
  unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
  asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" :: "r"(dst), "l"(gmem_src));
#else
  *reinterpret_cast<float4*>(smem_dst) = *reinterpret_cast<float4 const*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_4(void* smem_dst, void const* gmem_src) {
#if __CUDA_ARCH__ >= 800
  unsigned dst = static_cast<unsigned>(__cvta_generic_to_shared(smem_dst));
  asm volatile("cp.async.ca.shared.global [%0], [%1], 4;\n" :: "r"(dst), "l"(gmem_src));
#else
  *reinterpret_cast<float*>(smem_dst) = *reinterpret_cast<float const*>(gmem_src);
#endif
}
__device__ __forceinline__ void cp_async_commit_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.commit_group;\n" ::);
#endif
}
template <int W>
__device__ __forceinline__ void cp_async_wait_group() {
#if __CUDA_ARCH__ >= 800
  asm volatile("cp.async.wait_group %0;\n" :: "n"(W));
#endif
}
__global__ static void __launch_bounds__(256) matmul_kernel(
    int M, int N, int K,
    float const* __restrict__ A,
    float const* __restrict__ B,
    float* __restrict__ C)
{
#if __CUDA_ARCH__ >= 800
  constexpr int BM = 128;
  constexpr int BN = 128;
  constexpr int BK = 16;
  // Shared-memory operand layout matching the WMMA tf32 fragment loads:
  // A staged as [BM][BK] row-major, B staged as [BK][BN] row-major,
  // each with a +4-float skew so the 16-byte cp.async copies stay
  // contiguous/aligned and bank conflicts during fragment loads are
  // reduced.
  constexpr int LDA = BK + 4;   // A tile: [BM][LDA], k contiguous
  constexpr int LDB = BN + 4;   // B tile: [BK][LDB], n contiguous
  // Double-buffered shared-memory pipeline (37 KB static shared memory)
  __shared__ float smemA[2][BM * LDA];
  __shared__ float smemB[2][BK * LDB];
  int const tid  = threadIdx.x;
  int const m0   = blockIdx.x * BM;
  int const n0   = blockIdx.y * BN;
  int const kmax = K / BK;
  // Stage one (BM x BK) A-tile and one (BK x BN) B-tile into shared
  // memory using asynchronous vectorized (16B) global->shared copies.
  auto load_tile = [&](int k_tile, int stage) {
    // A tile: 128 rows of 16 floats = 512 float4; two per thread.
#pragma unroll
    for (int i = 0; i < 2; ++i) {
      int const flat = tid + i * 256;
      int const row  = flat >> 2;      // 0..127
      int const kh   = (flat & 3) * 4; // 0..12
      float const* src = A + (long)(m0 + row) * K + (long)k_tile * BK + kh;
      float*       dst = smemA[stage] + row * LDA + kh;
      cp_async_16(dst, src);
    }
    // B tile: 16 rows of 128 floats = 512 float4; two per thread.
#pragma unroll
    for (int i = 0; i < 2; ++i) {
      int const flat = tid + i * 256;
      int const kr   = flat >> 5;       // 0..15
      int const nc   = (flat & 31) * 4; // 0..124
      float const* src = B + (long)(k_tile * BK + kr) * N + n0 + nc;
      float*       dst = smemB[stage] + kr * LDB + nc;
      cp_async_16(dst, src);
    }
  };
  // Warp-level tiling: the 256 threads form 8 warps arranged as a 2x4
  // warp grid over the 128x128 CTA tile, so each warp owns a 64x32
  // sub-tile accumulated in 4x2 = 8 WMMA 16x16x8 tf32 fragments.
  int const warp   = tid >> 5;   // warp id (0..7)
  int const warp_m = warp & 1;   // warp row (0..1): 64 rows each
  int const warp_n = warp >> 1;  // warp col (0..3): 32 cols each
  using AFrag = wmma::fragment<wmma::matrix_a, 16, 16, 8,
                               wmma::precision::tf32, wmma::row_major>;
  using BFrag = wmma::fragment<wmma::matrix_b, 16, 16, 8,
                               wmma::precision::tf32, wmma::row_major>;
  using CFrag = wmma::fragment<wmma::accumulator, 16, 16, 8, float>;
  CFrag acc[4][2];
#pragma unroll
  for (int i = 0; i < 4; ++i) {
#pragma unroll
    for (int j = 0; j < 2; ++j) {
      wmma::fill_fragment(acc[i][j], 0.0f);
    }
  }
  // Prologue: fill the first pipeline stage.
  load_tile(0, 0);
  cp_async_commit_group();
  for (int k_tile = 0; k_tile < kmax; ++k_tile) {
    int const cur = k_tile & 1;
    // Prefetch the next k-tile into the other stage, then wait for the
    // current tile's copy group to land.
    if (k_tile + 1 < kmax) {
      load_tile(k_tile + 1, (k_tile + 1) & 1);
    }
    cp_async_commit_group();
    cp_async_wait_group<1>();  // allow the newest group to remain in flight
    __syncthreads();
    float const* sA = smemA[cur];
    float const* sB = smemB[cur];
    // Two tf32 k-steps (k = 8 each) per 16-deep tile.
#pragma unroll
    for (int ks = 0; ks < 2; ++ks) {
      AFrag af[4];
      BFrag bf[2];
#pragma unroll
      for (int i = 0; i < 4; ++i) {
        wmma::load_matrix_sync(af[i],
            sA + (warp_m * 64 + i * 16) * LDA + ks * 8, LDA);
      }
#pragma unroll
      for (int j = 0; j < 2; ++j) {
        wmma::load_matrix_sync(bf[j],
            sB + (ks * 8) * LDB + warp_n * 32 + j * 16, LDB);
      }
#pragma unroll
      for (int i = 0; i < 4; ++i) {
#pragma unroll
        for (int j = 0; j < 2; ++j) {
          wmma::mma_sync(acc[i][j], af[i], bf[j], acc[i][j]);
        }
      }
    }
    __syncthreads();
  }
  // Epilogue: store the 16x16 accumulator fragments directly to global
  // memory; each store_matrix_sync writes a coalesced 16x16 tile.
#pragma unroll
  for (int i = 0; i < 4; ++i) {
#pragma unroll
    for (int j = 0; j < 2; ++j) {
      float* dst = C + (long)(m0 + warp_m * 64 + i * 16) * N
                     + n0 + warp_n * 32 + j * 16;
      wmma::store_matrix_sync(dst, acc[i][j], N, wmma::mem_row_major);
    }
  }
#else
  // Portable fallback for pre-Ampere GPUs: scalar tiled-output GEMM.
  int const tid = threadIdx.x;
  int const m0  = blockIdx.x * 128;
  int const n0  = blockIdx.y * 128;
  for (int t = 0; t < 64; ++t) {
    int const idx = tid + t * 256;
    int const r = m0 + (idx >> 7);
    int const c = n0 + (idx & 127);
    float s = 0.0f;
    for (int k = 0; k < K; ++k) {
      s = fmaf(A[(long)r * K + k], B[(long)k * N + c], s);
    }
    C[(long)r * N + c] = s;
  }
#endif
}

torch::Tensor matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "A and B must be float32");

  int64_t M = A.size(0);
  int64_t K = A.size(1);
  int64_t N = B.size(1);
  TORCH_CHECK(B.size(0) == K, "Inner dimensions must match");
  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 16 == 0,
              "Dimensions must be multiples of the tile sizes (M,N % 128, K % 16)");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C = torch::empty({M, N}, A.options());

  dim3 block(256);
  dim3 grid((unsigned)(M / 128), (unsigned)(N / 128));

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  matmul_kernel<<<grid, block, 0, stream>>>(
      (int)M, (int)N, (int)K,
      A_c.data_ptr<float>(),
      B_c.data_ptr<float>(),
      C.data_ptr<float>());

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE matmul launch failed: ",
              cudaGetErrorString(err));

  return C;
}
"""

cute_matmul_ext = load_inline(
    name="cute_matmul_ext",
    cpp_sources=matmul_cpp_decl,
    cuda_sources=matmul_cuda_src,
    functions=["matmul"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "--expt-relaxed-constexpr"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single square matrix multiplication (C = A * B)
    using a custom tiled CUTE/CUDA GEMM kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self._ext = cute_matmul_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.matmul(A, B)

